def read(path):return json.loads(Path(path).read_text(encoding='utf-8'))
def write(path,value):Path(path).write_text(json.dumps(value,indent=2,allow_nan=False),encoding='utf-8')
def formatted(value):return '—' if value is None or pd.isna(value) else f'{value:.3f}' if isinstance(value,(float,np.floating)) else str(value)
def table(df,columns=None):
    df=df[columns] if columns else df
    return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+html.escape(c)+'</th>' for c in df.columns)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(formatted(v))+'</td>' for v in row)+'</tr>' for row in df.itertuples(index=False,name=None))+'</tbody></table></div>'

def aggregate_cdf(events,variant,key,bins):
    values=[]
    for e in events:
        if e['variant']!=variant:continue
        a=np.asarray(e[key]);
        if len(a):values.append(np.array([(a<=x).mean() for x in bins]))
    return np.mean(values,axis=0)

