    plt.style.use('seaborn-v0_8-whitegrid');cov=pd.read_csv(root/'coverage-summary.csv');selection=pd.read_csv(root/'selection-by-image.csv');events=read(root/'events-private.json');spatial=pd.read_csv(root/'spatial-by-image.csv')
