    axs[0].set_xticks(x,[v.replace('000000','') for v in s.image_id],rotation=30);axs[0].set(ylabel='Next-fixation error (pixels)',xlabel='Internal test scene');axs[0].legend(fontsize=7)
    keys=['expected_novelty','expected_info','expected_movement_cost','expected_task'];v=s[keys].mean().to_numpy();v[2]*=-1;axs[1].bar(['Novelty','Information','Movement','Task'],v,color=['#658d7e','#788cb1','#b34e38','#d1aa5c']);axs[1].axhline(0,color='#333',lw=.6);axs[1].set(ylabel='Probability-weighted utility contribution',title='Shared fixed spatial policy at human prefixes')
    fig.tight_layout();fig.savefig(out/'phase4a-selection.png',dpi=150);plt.close(fig)
    # Image-only summary densities. No photographs or individual paths published.
