def private_overlays(root,directory):
    directory=Path(directory);directory.mkdir(parents=True,exist_ok=True);examples=read(root/'examples-private.json');links=[]
    for image,e in examples.items():
        r=e['record'];im=load_image(r['image_path']);xy=np.array([[f['x'],f['y']] for f in r['fixations']]);cs=e['candidates'];fig,axs=plt.subplots(1,2,figsize=(12,4))
        for a in axs:a.imshow(im);a.set_xlim(0,640);a.set_ylim(400,0);a.grid(False)
        axs[0].plot(xy[:,0],xy[:,1],'-o',color='#ffd45b',lw=1.3,ms=4);axs[0].set_title(f"Human record: subject {r['participant']} / {r['task']}")
        for k,p in enumerate(xy):axs[0].annotate(str(k),p,fontsize=8,color='white')
        axs[1].scatter([c['x'] for c in cs],[c['y'] for c in cs],c=[c['probability'] for c in cs],s=35,cmap='Reds',edgecolor='white',lw=.4);axs[1].scatter(*xy[e['step']],marker='+',s=100,color='cyan',label='Current human fixation');axs[1].scatter(*e['next_xy'],marker='x',s=90,color='yellow',label='Next label (evaluation only)');axs[1].set_title('Frozen candidate set after observed prefix');axs[1].legend(fontsize=7,frameon=True,facecolor='white',framealpha=.9)
        for x,y,x2,y2 in e['target_box']:
            for ax in axs:ax.add_patch(Rectangle((x,y),x2-x,y2-y,fill=False,edgecolor='lime',lw=1.2))
        fig.suptitle(image+' · prepared geometry / target box in green');fig.tight_layout();name=image.replace('.jpg','.png');fig.savefig(directory/name,dpi=130);plt.close(fig);links.append('<h2>'+image+'</h2><img style="max-width:100%" src="'+name+'">')
    (directory/'index.html').write_text('<!doctype html><meta charset="utf-8"><title>Local private photographic overlays</title><h1>Local photographic diagnostics</h1><p>Original photos and individual paths are kept here for internal inspection; not copied to GitHub or the hosted aggregate report. First available record per scene, chosen without outcome-based selection.</p>'+''.join(links),encoding='utf-8')

def build(root,out,private=None):
    root=Path(root);out=Path(out);out.mkdir(parents=True,exist_ok=True);files=figures(root,out)
    if private:private_overlays(root,private)
    audit=read(root/'audit.json');uncertainty=read(root/'uncertainty.json');selection=pd.read_csv(root/'selection-summary.csv');coverage=pd.read_csv(root/'coverage-summary.csv');spatial=pd.read_csv(root/'spatial-summary.csv');transitions=pd.read_csv(root/'transition-summary.csv');s=selection[selection.split=='test'].iloc[0];full=spatial[spatial.variant=='full'].iloc[0]
    report=dict(scope='Phase 4A diagnostics only; production code, parameters, timing models and previous reports preserved',source_commit='7332703f609f578bda9e6966bd1fdca583379907',audit=audit,selection=json.loads(selection.to_json(orient='records')),coverage=json.loads(coverage.to_json(orient='records')),spatial=json.loads(spatial.to_json(orient='records')),transition=json.loads(transitions.to_json(orient='records')),uncertainty=uncertainty,sources=SOURCES,images=files,autonomous_runs=720,autonomous_scenes=6,autonomous_trials=60,prefix_trials=259,prefix_transitions=len(pd.read_csv(root/'prefix-private.csv')),aggregation='Average seeds/steps within image+participant+task; tasks within image+participant; participants within image; scenes equally. Image bootstrap 2000. Seeds are not scenes.',oracle='Future coordinate added to a copy of the frozen candidate set with nearest existing candidate utility. This changes coverage only and has no access to future semantics. Metrics only; never normal inference.',limits=['Exploratory, previously examined internal split of a small local mirror subset; not official benchmark test.','Reported 54x35 degree display geometry gives approximate ray angles, not individual calibration.','No raw event timestamps: response-time matching is approximate; lower-window and fixed-prefix sensitivities included.','SSDLite reference boxes are noisy evaluation proxies. Outside them is unclassified, not verified empty. All-object segmentation ground truth remains unavailable.','No model fitted or selected on this diagnostic test.'])
    write(out/'phase4a-results.json',report)
    for p in root.glob('*.csv'):
        if p.name.endswith(('-summary.csv','-by-image.csv','-by-participant.csv')):shutil.copy2(p,out/('phase4a-'+p.name))
    write(out/'phase4a-protocol.json',read(Path(__file__).resolve().parents[1]/'docs/phase4a-protocol.json'))
    def metric(key):
        v=uncertainty['selection']['test'][key];return f"{v['mean']:.3f} [{v['ci95'][0]:.3f}, {v['ci95'][1]:.3f}]"
    body='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Phase 4A · Spatial diagnosis</title><style>body{font:16px/1.6 system-ui;color:#243840;background:#f5f8f7;margin:0}main{max-width:1200px;margin:auto;padding:32px 22px 70px}nav{background:#11252e;padding:15px 24px;color:white;position:sticky;top:0;z-index:2;display:flex;gap:18px;flex-wrap:wrap}nav a{color:#b8e4d9}a{color:#176861}h1{font-size:38px;line-height:1.15}h2{margin-top:40px;line-height:1.3}h3{line-height:1.4}.lead{font-size:19px}.notice{padding:24px;border-left:4px solid #518b79;background:#e3efea}.scroll{overflow-x:auto;margin:18px 0}table{border-collapse:collapse;background:white;font-size:13px;min-width:700px;width:100%}td,th{padding:9px 12px;border:1px solid #d2ded8;text-align:left}th{background:#edf2ee}img{max-width:100%;height:auto}select{max-width:100%;padding:10px;border:1px solid #a9c5bb;border-radius:5px;background:white}.muted{color:#596e74;font-size:14px}li{margin:10px 0}code{font-size:13px;background:#e8edeb;padding:2px 4px}details{margin:18px 0;padding:15px;background:#edf2ef}summary{cursor:pointer;font-weight:600}</style><nav><a href="../index.html">← Timing lab</a><a href="#audit">Coordinate audit</a><a href="#coverage">Candidates</a><a href="#selection">Selection</a><a href="#behavior">Behavior</a><a href="#tasks">Tasks</a><a href="#bottlenecks">Bottlenecks</a></nav><main><p class="muted">RGB ACTIVE OBSERVER / PHASE 4A / DIAGNOSTICS ONLY</p><h1>Could the observer have looked where the human looked?</h1>'''
    body+=f'<p class="lead">Usually within a broad 48-pixel neighborhood, rarely at fine precision—and it assigns little probability to the relevant location. The main coarse-scale limitation is selection and task guidance, with a separate fine-scale candidate-resolution limitation.</p><div class="notice">On the six internal test scenes: candidate coverage at 48 px is {s.coverage_48:.1%}, at 16 px {s.coverage_16:.1%}. The nearest candidate ranks {s.nearest_rank_min:.1f} and receives {s.nearest_probability:.1%} probability. Mean nearest-location error is {s.nearest_error_px:.1f} px, versus {s.expected_error_px:.1f} px under the frozen policy. These are conditional, observed-prefix diagnostics—not autonomous prediction scores.</div>'
    body+='''<p>No attention, perception, timing or candidate-generation mechanism was added to normal inference. No test-set optimization occurred. The primary autonomous model is the frozen Phase 3 lognormal comparator, chosen to trace the reported amplitude discrepancy; the archived Phase 2 implementation remains the default. Existing center, salience and movement-prior policies serve as diagnostic baselines, all with the same frozen timing profile and three seeds.</p>
<h2 id="audit">1. Evaluation and coordinate audit</h2><p>The original coordinate frame is 1680 × 1050 display pixels. The mirror’s aspect-preserving black padding is reproduced before resizing to 640 × 400. Human x and y are both multiplied by 640/1680 = 400/1050. There is no crop. The adapter was reconstructed from the original fixation JSON using image + subject + task as the unique trial key.</p>'''
    body+=f'<p>Across {audit["trials"]} trials on {audit["images"]} scenes, maximum adapter discrepancy is {audit["max_adapter_error"]:.2g}; maximum coordinate round-trip error is {audit["max_roundtrip_error"]:.2g} original pixels. No fixation location was removed by the current RT truncation. Thus the amplitude gap is not explained by a scale-factor error in this adapter. Official display images were not locally available for pixelwise comparison, so the mirror-to-official stimulus match remains unverified.</p>'
    body+='''<p>The <a href="'''+SOURCES['published_protocol']+'''">authors’ published supplement</a> documents a 22-inch display at 47 cm, subtending approximately 54° × 35°. This report derives flat-display bearing rays from those angles and compares their angular separation. Rounded setup angles limit precision; this is not individual calibration. The protocol accepted calibration errors up to 0.51° on average and 0.94° maximum, so the smallest spatial tolerances must also be interpreted against measurement uncertainty. The mirror’s 16 px/degree pertains to COCO-Periph synthesis, and the model’s 60° pseudo-camera is a visualization assumption; neither is human display calibration. The model itself was not recalibrated.</p>'''
    body+=table(pd.read_csv(root/'audit-summary.csv'),['split','raw_count','window_count','initial_distance_from_center_px','amplitude_all_px','amplitude_exclude_first_px','duration_minus_rt_ms','terminal_duration_modified'])
    body+='''<p>The supplied initial fixation is excluded from fixation-density/count metrics. It is a nominal initial event, not a forced exact-center point: in this test subset its median distance from center is 28.5 px and maximum 114.2 px. Both model and human begin at that same recorded location. The published start-dot procedure alone cannot explain every offset; event-level provenance/calibration needs the raw recording, so the first-event convention remains an explicit assumption. Amplitude is reported both from all consecutive fixation transitions and after excluding the first transition. “Saccade amplitude” here means displacement between reported fixation centroids; the local file has no continuous samples from which to re-detect physiological saccades. Simulation stay segments are merged; subsequent same-location censor flags follow the final segment. Revisit means returning within 4% of image width after at least one intervening fixation, excluding an immediate neighboring fixation.</p>'''
    body+=f'<p>Timing remains a material evaluation limitation: raw ΣT exceeds RT in {audit["raw_T_exceeds_RT_trials"]}/{audit["trials"]} trials and is below RT in {audit["raw_T_below_RT_trials"]}. The legacy adapter clips cumulative fixation durations at RT, changing {audit["terminal_modified_trials"]} terminal intervals but removing no locations. Without onset timestamps and saccade gaps, exact wall-clock alignment cannot be reconstructed. RT-conditioned autonomous windows are retained for comparability; a lower-window sensitivity truncates model predictions at min(RT, Σ clipped human T), and an ordinal first-three-movement DTW removes reliance on exact onset timing. Neither is presented as a corrected ground-truth event stream. The frozen lognormal comparator starts with a 150 ms observation, versus a 230 ms mean recorded human initial event in this test subset; initial duration was not part of the complete-interior-fixation timing fit. This affects the available time for later movements and is another reason to retain window and ordinal sensitivities.</p>'
    body+='''<h2 id="coverage">2. Candidate coverage</h2><p>For each transition in all 259 eligible trials, the observer processes only the current and preceding human fixations. Its state is updated with those observed durations; unavailable human saccade gaps are not invented. Candidates and their probabilities are frozen before reading the next human coordinate. That next coordinate is used only as a scoring label. The 24 scenes retain their original internal train/validation/test labels. No fitting uses any split in this phase.</p><p>Uniform-grid and fixed multiscale baselines never use the next label. The multiscale set has 16 global centers plus current gaze and two fixed local rings, nominally 40 points; clipping can merge points near edges. Uniform-random 40-point coverage averages 32 predetermined random sets per prefix. The dense 160-point grid has a larger candidate budget and is explicitly not a fair equal-count architecture comparison.</p>'''
    body+=table(coverage[coverage.split=='test'],['candidate_set','count','nearest_error_px','nearest_error_deg','coverage_16','coverage_32','coverage_48','coverage_deg_1','coverage_deg_2','coverage_deg_4'])
    body+='<img src="phase4a-coverage.png" alt="Pixel and angular candidate coverage curves"><p>48 pixels is the current model’s central radius, roughly four degrees near the display center; it is a broad tolerance. High coverage there does not mean that exact human endpoints are represented. At 1–2° or 8–16 px, quantization is a substantial limitation.</p>'
    body+='<p>Observer coverage at 48 px, with image-bootstrap 95% interval: '+metric('coverage_48')+'. Nearest error (px): '+metric('nearest_error_px')+'. Full image- and participant-level tables are linked below.</p>'
    body+='''<h2 id="selection">3. Candidate generation versus selection</h2><p>The nearest candidate is the evaluation-only best available endpoint. Its rank, utility and probability expose selection errors separately from the nearest-distance quantization floor. Rank uses greater utility as better; rank-min/rank-max in the CSV explicitly handle ties. Expected error sums each candidate’s distance from the next human point weighted by its frozen softmax probability. It is a one-step conditional loss, not the autonomous DTW score.</p>'''
    body+=table(selection[selection.split=='test'],['candidate_count','nearest_rank_min','nearest_utility','nearest_probability','max_probability','effective_candidates','entropy_fraction','probability_within_32','probability_within_48','unexplored_region_probability','object_probability','nearest_is_region','nearest_is_object','nearest_is_stay','probability_on_padding','candidate_padding_fraction'])
    body+=f'<p>The policy’s expected error is {s.expected_error_px:.1f} px, split exactly into {s.nearest_error_px:.1f} px unavoidable error under the existing set plus {s.selection_excess_px:.1f} px excess from selection. Greedy selection on the same utilities gives {s.greedy_error_px:.1f} px: sampling diffuseness contributes, but taking the utility maximum still misses the human endpoint substantially. This is a diagnostic counterfactual; no greedy policy was installed.</p>'
    body+='''<div class="notice"><strong>Evaluation-only oracle-candidate experiment.</strong> Add the actual next human coordinate to a copy of the frozen candidate set and assign it the nearest existing candidate’s utility. All existing weights remain unchanged. This removes the coverage floor but does not supply future object identity or a privileged score. The oracle never enters normal inference or an autonomous trajectory.</div>'''
    body+=f'<p>Mean conditional error changes from {s.expected_error_px:.1f} to {s.oracle_added_expected_error_px:.1f} px; the new perfect-location candidate receives only {s.oracle_added_probability:.1%} probability. A perfect selector restricted to the existing candidates could instead reach the {s.nearest_error_px:.1f} px floor. Thus merely inserting better locations with the same weak priority would not solve the problem. The inherited-utility assumption is explicit; this does not prove that better visual representations would have no benefit.</p>'
    body+='<details><summary>Inspect test candidate diagnostics by image</summary>'+table(pd.read_csv(root/'selection-by-image.csv').query('split=="test"'),['image_id','nearest_error_px','coverage_16','coverage_48','nearest_rank_min','nearest_probability','probability_within_48','probability_on_padding'])+'</details>'
    body+='<details><summary>Inspect test candidate diagnostics by participant</summary>'+table(pd.read_csv(root/'selection-by-participant.csv').query('split=="test"'),['participant','nearest_error_px','coverage_16','coverage_48','nearest_rank_min','nearest_probability','probability_within_48','probability_on_padding'])+'</details>'
    body+='<img src="phase4a-selection.png" alt="Per-scene coverage floor, selection error and evaluation-only oracle, with utility contributions">'
    body+=f'<p>Unexplored grid regions receive {s.unexplored_region_probability:.1%} of probability. Their probability-weighted novelty and information contributions average +{s.expected_novelty:.3f} and +{s.expected_info:.3f}, compared with movement cost −{s.expected_movement_cost:.3f} and task contribution +{s.expected_task:.3f}. “Unexplored” is a model state, not evidence of physical emptiness. These observed magnitudes support investigating prioritization and movement calibration; they do not independently identify the optimal weights.</p>'
    body+=table(transitions[transitions.split=='test'],['first_transition','target_term_any','next_on_target_box','probability_on_target_box','nearest_rank_min','expected_error_px','expected_amplitude_px','human_amplitude_px'])
    body+=table(pd.read_csv(root/'target-state-summary.csv').query('split=="test"'),['current_on_target_box','next_on_target_box','probability_on_target_box','target_term_any','nearest_rank_min','probability_within_48'])
    body+='''<p>In these test trials, the first-choice target utility is always zero: central-only recognized labels cannot guide gaze toward a still-peripheral target. Context utility is also zero under the empty context-prior configuration. The next human fixation often lands on the annotated target, while the policy allocates only a small fraction of its probability there. The target string is supplied, but learned target-feature matching across peripheral candidate locations is absent. When the current human fixation is already inside the target box, the next human point stays inside it about 94% of the time, versus only 16.7% assigned probability from the model. This shows a prioritization/verification mismatch even after some target evidence becomes available; it is not explained solely by initial detection failure.</p>
<h2 id="behavior">4. Autonomous spatial behavior</h2><p>60 trials × three common seeds × four fixed existing policies = 720 runs on six previously examined internal test scenes. Seeds are averaged inside each trial; tasks inside image/participant; participants inside image; scenes equally. Bootstrap intervals resample scenes, never seed runs as if they were independent images. Only six scenes makes all intervals exploratory and unstable.</p>'''
    body+=table(spatial,['variant','model_amplitude_all_px','human_amplitude_all_px','model_amplitude_exclude_first_px','human_amplitude_exclude_first_px','model_amplitude_all_deg','human_amplitude_all_deg','model_amplitude_exclude_first_deg','human_amplitude_exclude_first_deg','amplitude_w1_all_px','nss','spatial_dtw'])
    body+='<img src="phase4a-amplitudes.png" alt="Human and four model amplitude distributions with first transition sensitivity and angular geometry">'
    body+=f'<p>With the first transition included, the observer mean is {full.model_amplitude_all_px:.1f} px versus human {full.human_amplitude_all_px:.1f}; excluding it gives {full.model_amplitude_exclude_first_px:.1f} versus {full.human_amplitude_exclude_first_px:.1f}. The discrepancy therefore survives the convention change, although its ratio changes substantially. The lower-window sensitivity leaves the full observer amplitude at 198.6 px (all transitions), essentially unchanged from 198.5 px. These are image/observer means, not pooled saccades, and later-transition means omit trials with no later transition rather than assigning zeros.</p>'
    body+='<p>Later-transition means above have different valid support when a model or human has only one transition. The following common-support sensitivity retains only paired runs where both have a later transition; it confirms the gap without assigning missing movements a zero.</p>'+table(pd.read_csv(root/'later-paired-summary.csv'))
    body+=table(spatial,['variant','model_center_distance_diag','human_center_distance_diag','model_refixation_rate','human_refixation_rate','model_target_ever','human_target_ever','model_target_first_saccade','human_target_first_saccade','model_post_initial_count','human_post_initial_count','lower_window_count','first3_sequence_dtw'])
    body+='''<p>In this correct-response test subset, humans fixate the annotated target on every trial; the observer does so in only 18.3% of matched-window runs. The center prior has higher NSS than the observer (0.154 vs 0.092) but lower target acquisition (6.7% vs 18.3%). The movement prior shortens jumps yet has negative NSS and reaches the target in only 2.8% of runs. These baselines expose dissociations; they do not establish a better observer. Center distance is normalized by image diagonal. Target-box metrics use the raw trial’s (x, y, width, height) target annotation, transformed identically to gaze. A point inside a target bounding box is a coarse target-selection proxy, not proof of recognition. The ordinal first-three-movement DTW includes the shared supplied starting point, unlike the post-initial full-sequence metric; the two DTW columns therefore have different conventions. Target acquisition, center bias, short movement size and density similarity must be assessed together; matching amplitude alone is insufficient.</p>'''
    body+=table(spatial,['variant','model_reference_object_fraction','human_reference_object_fraction','model_object_dwell_fraction','human_object_dwell_fraction','model_known_annotation_fraction','human_known_annotation_fraction','model_small_step_fraction','human_small_step_fraction','model_padding_fraction','human_padding_fraction'])
    body+='''<p><strong>Objects versus empty regions:</strong> complete ground-truth object masks are not available locally. The report therefore uses two explicit proxies: known search-object annotation boxes and a separate full-image SSDLite reference pass. This un-gated pass is evaluation-only and never supplied to the observer. Detector misses and box background mean that outside-reference locations are <em>unclassified</em>, not confirmed empty. True object/background allocation remains unresolved until complete COCO instance/stuff masks or OSIE contours are available.</p>
<h3>Confirmed padding artifact</h3><p>The fixed grid includes artificial black padding as if it were ordinary unexplored image space. It receives 13.8% of conditional probability; 15.9% of autonomous observer fixations land there, versus 0% for humans in this subset. Unlike outside-detector areas, these strips are known display padding rather than unknown scene content. This is a concrete preprocessing/candidate-validity problem, retained here for diagnosis rather than masked after inspecting the test results.</p><h3>Per-image density diagnostics</h3><p>Each image panel compares coarse normalized fixation-count densities, excludes initial fixation, and overlays human density with the observer’s contours. Shared color limits within a scene show concentration differences. Original photographs and individual trajectories are generated separately as local private overlays; they are not redistributed in this aggregate report.</p><label for="scene-select">Internal test scene </label><select id="scene-select">'''
    body+=''.join('<option value="'+f['file']+'">'+f['image_id']+'</option>' for f in files)+'</select><figure><img id="image-diagnostic" src="'+files[0]['file']+'" alt="Per-image human and model density comparison"></figure>'
    body+='<details><summary>Inspect autonomous results by image</summary>'+table(pd.read_csv(root/'spatial-by-image.csv'),['variant','image_id','model_amplitude_all_px','human_amplitude_all_px','nss','spatial_dtw','model_target_ever','model_padding_fraction'])+'</details>'
    body+='<details><summary>Inspect autonomous results by participant</summary>'+table(pd.read_csv(root/'spatial-by-participant.csv'),['variant','participant','model_amplitude_all_px','human_amplitude_all_px','nss','spatial_dtw','model_target_ever','model_padding_fraction'])+'</details>'
    paired=[]
    for variant,metrics in uncertainty['paired_baseline_minus_full'].items():
        for name,v in metrics.items():paired.append(dict(baseline=variant,metric=name,delta=v['mean'],ci_low=v['ci95'][0],ci_high=v['ci95'][1]))
    body+='<details><summary>Paired baseline-minus-observer intervals</summary><p>Image-bootstrap 95% intervals; higher NSS/target acquisition and lower DTW/W1 are favorable. Amplitude change itself has no intrinsically favorable sign. No multiplicity correction or population superiority claim.</p>'+table(pd.DataFrame(paired))+'</details>'
    body+='''<h2 id="tasks">5. The task is not free exploration</h2><p>Free exploration asks what attracts or informs gaze without a specified target. Goal-directed search adds a target-specific priority and a decision to stop searching. The current model is mainly an uncertainty/novelty explorer with a target-label bonus after central recognition. It has no learned peripheral target-template matching, no populated context priors in the tested profile, and no predicted response decision in this comparison. Human RT supplies the exposure budget. It does not adequately implement the human search task, and failure on that task does not by itself establish how well it would explain free viewing.</p>'''
    body+='<div class="scroll"><table><thead><tr><th>Mode</th><th>Recommended data</th><th>Purpose and constraint</th></tr></thead><tbody>'
    for mode,name,url,reason in [('Free exploration, first priority','COCO-FreeView',SOURCES['freeview'],'Same image family as COCO-Search18, no cued target, fixed five-second viewing. Supports a clean task comparison using released splits; obtain official assets and timing metadata.'),('Free exploration, object allocation','OSIE',SOURCES['osie'],'700 scenes, 15 viewers and detailed object/semantic annotations. Particularly useful for testing whether gaze is allocated to objects and which semantic properties matter.'),('Free exploration, spatial baseline','MIT1003',SOURCES['mit1003'],'1003 images and 15 viewers. Useful independent spatial/center-bias validation; free viewing is not robotic active exploration.'),('Goal-directed search','COCO-Search18',SOURCES['dataset'],'Retain with a separately declared target-search model and official geometry; use genuinely new scenes and registered splits. Evaluate target acquisition as well as density and sequence statistics.'),('Later dynamic observation','GazeCom',SOURCES['dynamic'],'Natural-video eye movements for future temporal tracking and pursuit work. Dynamic viewing is a separate task; it does not by itself validate head or camera control.')]:body+='<tr><td>'+mode+'</td><td><a href="'+url+'">'+name+'</a></td><td>'+reason+'</td></tr>'
    body+='</tbody></table></div><p>These are recommendations for future validation, not datasets newly fitted or evaluated in Phase 4A. The current local subset covers only 24 scenes and a subset of target categories. An environment-learning or robotic observer will eventually need action-conditioned sensory streams and head/eye measurements beyond static screen-viewing datasets.</p>'
    body+='''<h2 id="bottlenecks">6. Ranked bottlenecks and what the evidence supports</h2><ol>
<li><strong>Confirmed: search-task representation is incomplete.</strong> No initial peripheral target-label utility, zero context contribution, and a large human/model target-allocation mismatch. This is a prerequisite mismatch, not a timing problem.</li>
<li><strong>Confirmed: spatial candidate selection is weak even when coarse coverage exists.</strong> Near-human candidates commonly exist but rank poorly and receive little probability. The oracle-location experiment leaves most expected error intact when priority is inherited.</li>
<li><strong>Confirmed: artificial padding remains selectable.</strong> About one in six observer fixations lands outside the actual photograph, despite no such human fixations in this subset. The coordinate transformation can be correct while candidate validity is wrong. A future padding-mask fix should be isolated and tested on new scenes.</li>
<li><strong>Confirmed behavior; suspected calibration cause: long jumps and diffuse exploration.</strong> The amplitude gap survives coordinate and first-transition checks; most conditional probability favors unexplored grid regions. Greedy rescoring reduces error but does not solve it. Movement and novelty/information weights were never behaviorally calibrated; this phase does not establish which adjustment would be optimal.</li>
<li><strong>Confirmed: fine endpoint precision is limited.</strong> The 8×5 grid gives weak small-tolerance coverage. Multiscale and denser evaluation-only proposals quantify this; adding candidates alone is not demonstrated to improve autonomous search.</li>
<li><strong>Confirmed evaluation limits:</strong> approximate event-window alignment, few reused scenes, incomplete object masks, and task-conditioned trial aggregation. These constrain causal and generalization claims even though the coordinate scale is consistent.</li>
<li><strong>Suspected contributor: perceptual quality and memory association.</strong> Central recognition and accumulated proto-objects may miss or merge relevant objects. Prefix cue availability and reference detections expose this issue, but ground-truth detector/association accuracy was not established here.</li>
</ol><p><strong>Next evidence milestone:</strong> obtain official stimuli, event onset/offset records and object masks; declare exploration versus search; register new validation scenes and a target-acquisition endpoint. Use these diagnostics to decide a narrowly scoped next model change. Do not add another timing mechanism on the basis of this pilot.</p>'''
    body+='<h2>Reproducibility and aggregate downloads</h2><p>Existing model implementations, configurations and Phase 2/3 reports are preserved. A <a href="phase4a-integrity.json">SHA256 integrity ledger</a> verifies 54 existing source/configuration/report files against the Phase 3 baseline. All oracle/reference computations are confined to evaluation scripts. See <a href="phase4a-results.json">machine-readable results and uncertainty</a>, <a href="phase4a-protocol.json">pre-run diagnostic protocol</a>, and <a href="https://github.com/tamayowang-lab/single-view-image-rectification/tree/feature/rgb-active-observer-v1/rgb-active-observer">source branch</a>.</p><ul>'
    for stem in ['audit','coverage','selection','transition','target-state','later-paired','spatial']:
        for suffix in ['summary','by-image','by-participant']:body+='<li><a href="phase4a-'+stem+'-'+suffix+'.csv">'+stem+' / '+suffix+'</a></li>'
    body+='</ul><p class="muted">Raw human events, original photos, local reference boxes and cached predictions remain local. All results are descriptive diagnostics of an exploratory internal subset, not official benchmark performance or proof of humanlike cognition.</p><script>document.getElementById("scene-select").onchange=e=>{document.getElementById("image-diagnostic").src=e.target.value};</script></main></html>'
    (out/'phase4a-report.html').write_text(body,encoding='utf-8')
